{-# INLINE mainRecordStatusL #-}

mainRecordSinceL :: Lens' MainRecord (String)
mainRecordSinceL k r = (\v -> r { mainRecordSince = v }) <$> k (mainRecordSince r)
{-# INLINE mainRecordSinceL #-}

